const states = ['reported', 'triaged', 'fixed', 'verified', 'closed'];
for (const s of states) {
  console.log('-> ' + s);
}

const bugs = [
  { id: 1, severity: 9 },
  { id: 2, severity: 3 },
  { id: 3, severity: 10 }
];
for (const b of bugs) {
  if (b.severity > 8) {
    console.log('bug ' + b.id + ' is critical');
  }
}

